import 'package:equatable/equatable.dart';
import 'package:sehatak/core/models/dental/dental_models.dart';
class DentalState extends Equatable { final bool isLoading; final List<DentalDoctor> doctors; final List<DentalClinic> clinics; final List<DentalTip> tips; final List<DentalHospital> hospitals; final String? errorMessage; const DentalState({this.isLoading=false,this.doctors=const [],this.clinics=const [],this.tips=const [],this.hospitals=const [],this.errorMessage}); DentalState copyWith({bool? isLoading,List<DentalDoctor>? doctors,List<DentalClinic>? clinics,List<DentalTip>? tips,List<DentalHospital>? hospitals,String? errorMessage,bool clearError=false})=>DentalState(isLoading:isLoading??this.isLoading,doctors:doctors??this.doctors,clinics:clinics??this.clinics,tips:tips??this.tips,hospitals:hospitals??this.hospitals,errorMessage:clearError?null:(errorMessage??this.errorMessage)); @override List<Object?> get props=>[isLoading,doctors,clinics,tips,hospitals,errorMessage]; }
